function crearValidador(minLength, maxLength) {
  return function (texto) {
    if (texto.length < minLength) return `Mínimo ${minLength} caracteres`;
    if (texto.length > maxLength) return `Máximo ${maxLength} caracteres`;
    return 'válido';
  };
}

const validarNombre = crearValidador(2, 50);
const validarPin = crearValidador(4, 4);

console.log(validarNombre('Al'));    // válido
console.log(validarNombre('A'));     // Mínimo 2 caracteres
console.log(validarPin('1234'));     // válido
console.log(validarPin('12345'));    // Máximo 4 caracteres

function crearContadorEventos(elemento) {
  let clicks = 0; // Privado al closure

  elemento.addEventListener('click', () => {
    clicks++;
    console.log(`Clicks: ${clicks}`);
  });

  return () => clicks; // Getter público
}

